<script>
import { Component, Prop, Vue } from "vue-property-decorator";
import { Fragment } from "vue-fragment";
import { MobileSwitchSlot } from "./mobile-switch.constants";

@Component({ components: { Fragment } })
export default class MobileSwitch extends Vue {
  @Prop({ type: Number, default: 768 }) media;
  mediaQuery = null;
  currentMedia = -1;
  isMobile = false;
  MobileSwitchSlot = MobileSwitchSlot;

  beforeMount() {
    this.registerMedia();
  }

  updated() {
    this.registerMedia();
  }

  beforeDestroy() {
    this.mediaQuery?.removeListener(this.handleMediaQuery);
  }

  registerMedia() {
    if (this.currentMedia === this.media) return;
    this.mediaQuery?.removeListener(this.handleMediaQuery);
    this.mediaQuery = window.matchMedia(
      `(min-width: 0px) and (max-width: ${this.media}px)`
    );
    this.handleMediaQuery(this.mediaQuery);
    this.mediaQuery.addListener(this.handleMediaQuery);
    this.currentMedia = this.media;
  }

  handleMediaQuery(query) {
    if (query.matches) {
      this.isMobile = true;
    } else {
      this.isMobile = false;
    }
  }
}
</script>

<template>
  <Fragment>
    <slot v-if="isMobile" :name="MobileSwitchSlot.MOBILE" />
    <slot v-if="!isMobile" :name="MobileSwitchSlot.DESKTOP" />
  </Fragment>
</template>
